use parking_lot::RwLock;

let table = RwLock::new(HashMap::<String, i32>::new());
{
    let read = table.read();               // shared
    assert!(read.get(key).is_some());
}
{
    let mut write = table.write();         // exclusive
    write.insert(key.to_string(), 1);
}

let table = Arc::new(tokio::sync::RwLock::new(HashMap::<String, i32>::new()));

let read = table.read().await;             // shared, task yields
let value = read.get(key).copied();
drop(read);

let mut write = table.write().await;       // exclusive, write-preferring
write.insert(key.to_string(), value);
